import { createServer } from "node:http";
import { readFile } from "node:fs/promises";
import { extname, join, normalize } from "node:path";
import { fileURLToPath } from "node:url";

const root = join(fileURLToPath(new URL(".", import.meta.url)), "..", "src");
const port = Number(process.env.PORT || 4877);
const types = { ".html": "text/html", ".js": "text/javascript", ".css": "text/css", ".woff2": "font/woff2", ".png": "image/png", ".json": "application/json" };

createServer(async (req, res) => {
  const url = new URL(req.url, "http://x");
  const rel = normalize(decodeURIComponent(url.pathname)).replace(/^(\.\.[/\\])+/, "");
  const file = join(root, rel === "/" ? "index.html" : rel);
  try {
    const buf = await readFile(file);
    res.writeHead(200, { "content-type": types[extname(file)] || "application/octet-stream", "cache-control": "no-store" });
    res.end(buf);
  } catch {
    res.writeHead(404);
    res.end("not found");
  }
}).listen(port, "127.0.0.1", () => console.log(`serving ${root} on ${port}`));

const page = await browser.getPage("wsq0bo-render");
await page.setViewportSize({ width: 1920, height: 1080 });
const errs = [];
page.on("pageerror", (e) => errs.push("PAGEERR " + e.message));
await page.goto("http://127.0.0.1:4877/?v=" + Date.now());
await page.waitForFunction(() => window.__ready === true, null, { timeout: 15000 });
const times = [10.6, 12.2, 14.2, 17.2, 19.6, 21.5, 22.6];
for (const t of times) {
  await page.evaluate((tt) => window.__seek(tt), t);
  const buf = await page.screenshot();
  await saveScreenshot(buf, "wsq0bo-p-" + String(t).replace(".", "_") + ".png");
}
console.log(JSON.stringify({ errs }));

export const BPM = 128;
export const BEAT = 60 / BPM;
export const DURATION = 45;
export const b = (n) => n * BEAT;

export const S = {
  s1: 0,
  s2: b(10),
  s3: b(20),
  s4: b(34),
  s5: b(50),
  s6: b(64),
  s7: b(74),
  s8a: b(84),
  s8b: b(89),
};

export const T = {
  flood1: [b(10) - 0.55, b(10), b(10) + 0.5],
  slide2: [S.s3 - 0.6, S.s3],
  slide3: [S.s4 - 0.6, S.s4],
  fade4: [S.s5 - 0.55, S.s5],
  slide5: [S.s6 - 0.6, S.s6],
  flood6: [S.s7 - 0.55, S.s7, S.s7 + 0.5],
  zoom7: [S.s8a - 0.55, S.s8a],
  iris8: [S.s8b - 0.6, S.s8b],
};

