.pw.fin .fl{color:var(--flare)}
.pw .fl{color:var(--flare)}
.frag{position:absolute;visibility:hidden}
.tpl{position:absolute;width:250px;height:330px;border-radius:20px;background:#121417;border:1px solid rgba(255,255,255,.12);padding:24px}
.tpl i{display:block;height:74px;border-radius:10px;background:#1f2328;margin-bottom:18px}
.tpl b{display:block;height:13px;border-radius:7px;background:#2a2f36;margin-bottom:13px}
.tpl b.s{width:60%}
.tpl .x{position:absolute;right:-16px;top:-16px;width:46px;height:46px;border-radius:50%;background:var(--flare);color:#fff;display:flex;align-items:center;justify-content:center;font-size:26px;font-weight:700}
.setcard{position:absolute;width:560px;padding:26px 30px;border-radius:26px;background:#121417;border:1px solid rgba(255,255,255,.12)}
.setrow{display:flex;align-items:center;justify-content:space-between;height:66px}
.setrow s{display:block;height:15px;border-radius:8px;background:#2a2f36;text-decoration:none}
.tog{position:relative;width:74px;height:40px;border-radius:999px;background:#2a2f36}
.tog::after{content:"";position:absolute;top:5px;left:5px;width:30px;height:30px;border-radius:50%;background:#8a8f98;transform:translateX(var(--k,0px))}
.clockwrap{position:absolute;width:460px;height:460px}
