@font-face{font-family:"Geist";src:url(fonts/Geist-Variable.woff2) format("woff2");font-weight:100 900;font-display:block}
@font-face{font-family:"Geist Mono";src:url(fonts/GeistMono-Variable.woff2) format("woff2");font-weight:100 900;font-display:block}

:root{
  --void:#08090a; --ink:#1a1614; --paper:#f8f7f4; --flare:#ff3300; --coral:#ff633d;
  --wash:#fbeee7; --peach:#ffe3d9; --line:#e6e1da; --muted:#5f5853; --muted-d:#8a8f98;
  --green:#0a7f64; --band:#f1efeb;
  --mono:"Geist Mono",ui-monospace,monospace;
  --shadow-card:0 1px 2px rgba(26,22,20,.05),0 34px 70px -34px rgba(26,22,20,.28);
}
*{box-sizing:border-box;margin:0;padding:0}
html,body{width:1920px;height:1080px;overflow:hidden;background:#000}
body{font-family:"Geist",Inter,system-ui,sans-serif;color:var(--ink);-webkit-font-smoothing:antialiased;text-rendering:geometricPrecision}
#stage{position:relative;width:1920px;height:1080px;overflow:hidden;background:var(--paper)}
.scene{position:absolute;inset:0;overflow:hidden;background:var(--paper);visibility:hidden}
.scene.dark{background:var(--void);color:#f7f8f8}
.cam{position:absolute;inset:0;transform-origin:50% 50%}
.abs{position:absolute}
svg.ic{width:1em;height:1em;fill:none;stroke:currentColor;stroke-width:2;stroke-linecap:round;stroke-linejoin:round;flex:none}
svg.ic.fill{fill:currentColor;stroke:none}

/* signature hatched rails */
.rails{position:absolute;inset:0;pointer-events:none}
.rails::before,.rails::after{content:"";position:absolute;top:0;bottom:0;width:120px;background:repeating-linear-gradient(135deg,transparent 0 5px,rgba(26,22,20,.085) 5px 6px);background-position:var(--rx,0px) 0}
.rails::before{left:0;border-right:1px solid var(--line)}
.rails::after{right:0;border-left:1px solid var(--line)}
.dark .rails::before,.dark .rails::after{background:repeating-linear-gradient(135deg,transparent 0 5px,rgba(255,255,255,.07) 5px 6px);border-color:rgba(255,255,255,.09)}

/* masks */
.ml{display:inline-block;overflow:hidden;vertical-align:top;padding:.08em .06em .2em;margin:-.08em -.06em -.2em}
.mi{display:inline-block;will-change:transform}
.ln{display:block;overflow:hidden;padding:.06em .04em .2em;margin:-.06em -.04em -.2em}
.ln>span{display:block}

/* pill (eyebrow) */
.pill{display:inline-flex;align-items:center;gap:12px;padding:10px 22px 10px 20px;border-radius:999px;background:var(--peach);color:var(--ink);font-size:24px;font-weight:500;letter-spacing:-.01em;white-space:nowrap}
.pill::before{content:"";width:10px;height:10px;border-radius:50%;background:var(--ink)}

/* headline chip */
.chip{display:inline-flex;align-items:center;gap:.18em;padding:0 .22em;margin:0 .06em;border-radius:.26em;background:#fff;border:1px solid var(--line);color:var(--flare);line-height:1.12;white-space:nowrap;vertical-align:baseline;transform:translateY(-.03em);box-shadow:0 1px 2px rgba(26,22,20,.05),0 6px 18px -10px rgba(26,22,20,.2)}
.chip svg{width:.72em;height:.72em;flex:none}

/* buttons */
.btn{display:inline-flex;align-items:center;justify-content:center;gap:14px;height:88px;padding:0 44px;border-radius:22px;background:var(--flare);color:#fff;font-size:34px;font-weight:500;letter-spacing:-.01em;box-shadow:inset 0 -5px 0 rgba(0,0,0,.2),0 18px 36px -14px rgba(255,51,0,.55);white-space:nowrap}
.btn svg{width:1em;height:1em}
.btn.ghost{background:#fff;color:var(--ink);border:1px solid var(--line);box-shadow:0 1px 2px rgba(26,22,20,.05)}
.btn.sm{height:60px;font-size:24px;padding:0 30px;border-radius:999px;box-shadow:none}
.btn.white{background:#f7f8f8;color:var(--void);box-shadow:none;border-radius:999px}

/* washes and cards */
.wash{position:absolute;background:var(--wash);border-radius:44px}
.card{position:absolute;background:#fff;border:1px solid var(--line);border-radius:28px;box-shadow:var(--shadow-card);overflow:hidden}
.win-head{display:flex;align-items:center;gap:12px;height:76px;padding:0 28px;border-bottom:1px solid var(--line);font-family:var(--mono);font-size:21px;color:#3a3532}
.win-head .dots{display:flex;gap:11px;margin-right:12px}
.win-head .dots i{width:15px;height:15px;border-radius:50%;background:#e6e2dc}
.badge-mono{margin-left:auto;display:flex;align-items:center;gap:10px;font-family:var(--mono);font-size:16px;color:#3a3532;border:1px solid var(--line);border-radius:9px;padding:6px 12px}
.badge-mono::before{content:"";width:9px;height:9px;border-radius:50%;background:var(--green)}

h2.h2{font-size:78px;line-height:1.04;letter-spacing:-.04em;font-weight:500}
p.lead{font-size:32px;line-height:1.55;color:var(--muted);letter-spacing:-.005em}
.col{position:absolute}

/* terminal */
.term-body{padding:34px 34px 30px;font-family:var(--mono);font-size:23px;line-height:1.5;color:var(--ink)}
.tl{margin-bottom:18px;position:relative;min-height:1.5em}
.tl .g{display:inline-block;width:12px;height:12px;border-radius:50%;background:var(--green);margin-right:14px;vertical-align:1px}
.tl .fn{color:var(--ink)} .tl .mcp{color:#8a847d}
.tl.res{padding-left:30px;color:#6b655f;margin-top:-6px}
.tl.res::before{content:"";position:absolute;left:8px;top:4px;width:12px;height:14px;border-left:1.5px solid #b9b2a9;border-bottom:1.5px solid #b9b2a9}
.tl.res b{font-weight:500;color:var(--ink)}
.tl.prompt{color:#9b948c;margin-bottom:26px}
.tl.prompt .pt{color:var(--ink)}
.tl.done{color:var(--ink)}
.caret{display:inline-block;width:12px;height:1.05em;background:var(--ink);vertical-align:-.16em;margin-left:2px}
.inputbox{margin-top:14px;border:1px solid var(--line);border-radius:14px;background:#faf9f7;padding:16px 20px;color:#9b948c;font-family:var(--mono);font-size:23px}
.inputbox .pt{color:var(--ink)}

/* code */
.code{padding:34px 34px 30px;font-family:var(--mono);font-size:25px;line-height:1.62;color:var(--ink);white-space:pre}
.code .k{color:var(--flare)} .code .s{color:var(--green)} .code .c{color:#8a847d}
.q-ok{display:flex;align-items:center;gap:12px;margin-top:22px;padding-top:0;font-family:var(--mono);font-size:22px;color:var(--green)}

/* footer marquee */
.migrate{position:absolute;left:121px;right:121px;bottom:0;height:120px;border-top:1px solid var(--line);background:var(--paper);overflow:hidden}
.migrate .lab{position:absolute;left:48px;top:0;bottom:0;display:flex;align-items:center;font-size:26px;color:var(--muted);z-index:2;background:var(--paper);padding-right:26px}
.migrate .track{position:absolute;left:0;top:0;bottom:0;display:flex;align-items:center;gap:44px;white-space:nowrap;will-change:transform}
.brand-chip{display:inline-flex;align-items:center;gap:14px;font-size:28px;font-weight:500;letter-spacing:-.01em}
.brand-chip i{width:38px;height:38px;border-radius:10px;display:inline-flex;align-items:center;justify-content:center;font-style:normal;font-weight:700;font-size:22px;color:#fff}

/* steps */
.steps{list-style:none;margin-top:44px}
.steps li{display:flex;align-items:center;gap:28px;font-size:34px;letter-spacing:-.015em;height:78px;position:relative}
.steps li .n{font-family:var(--mono);font-size:22px;color:var(--muted-d);width:40px}
.steps li:not(:last-child)::after{content:"";position:absolute;left:19px;top:66px;height:24px;border-left:1.5px solid var(--line)}

/* highlight sweep */
.hilite{position:relative;display:inline-block;padding:0 .12em;margin:0 -.04em}
.hilite::before{content:"";position:absolute;inset:.08em 0 .02em 0;background:var(--peach);z-index:-1;transform-origin:0 50%;transform:scaleX(var(--hp,0))}
.hilite{z-index:0;isolation:isolate}

/* editor */
.tb{display:flex;gap:14px;padding:22px 24px 18px}
.tb .grp{display:flex;align-items:center;gap:6px;padding:7px 8px;background:#fff;border:1px solid var(--line);border-radius:14px}
.tb .b{width:44px;height:42px;border-radius:9px;display:flex;align-items:center;justify-content:center;font-size:22px;color:#3a3532}
.tb .b.on{background:#eceae6}
.doc{margin:0 24px;background:#fff;border-radius:18px;padding:34px 36px 30px;min-height:470px}
.doc h3{font-size:46px;line-height:1.25;letter-spacing:-.03em;font-weight:700;color:#0f172a;margin-bottom:22px;min-height:1.25em}
.doc p{font-size:26px;line-height:1.55;color:#2c3340;margin-bottom:18px}
.doc .var{display:inline-flex;align-items:center;gap:8px;padding:0 12px;border-radius:12px;background:#f0efee;border:1px solid var(--line);font-size:.92em;line-height:1.3;color:#2c3340}
.doc .var em{font-style:normal;color:var(--flare);font-family:var(--mono);font-size:.8em}
.doc p.sel .selbg{background:rgba(255,99,61,.22);border-radius:4px;box-decoration-break:clone;-webkit-box-decoration-break:clone}
.foot-mono{display:flex;align-items:center;height:64px;padding:0 28px;margin-top:22px;border-top:1px solid var(--line);font-family:var(--mono);font-size:17px;color:#6b655f;background:#fff}
.ai-pop{position:absolute;display:flex;align-items:center;gap:10px;padding:12px 20px;border-radius:14px;background:var(--ink);color:#fff;font-size:22px;font-weight:500;box-shadow:0 18px 40px -12px rgba(26,22,20,.5)}
.ai-pop svg{color:var(--coral)}

/* workflow */
.wf{position:absolute;left:50%;top:0;width:560px;margin-left:-280px}
.node{position:absolute;left:0;width:560px;height:100px;border:1px solid var(--line);border-radius:18px;background:#fff;display:flex;align-items:center;gap:20px;padding:0 24px}
.node .ni{width:56px;height:56px;border-radius:14px;background:#f2f0ec;display:flex;align-items:center;justify-content:center;font-size:28px;color:#3a3532;flex:none}
.node .nt{font-size:27px;font-weight:500;letter-spacing:-.01em;line-height:1.2}
.node .ns{font-size:21px;color:var(--muted);margin-top:3px}
.wire{position:absolute;left:280px;width:2px;background:var(--line);margin-left:-1px}
.branch{position:absolute;top:0;width:270px;height:64px;border:1px solid var(--line);border-radius:14px;background:#fff;display:flex;align-items:center;gap:14px;padding:0 22px;font-size:24px}
.branch i{width:11px;height:11px;border-radius:50%}
.travel{position:absolute;left:280px;width:26px;height:26px;margin:-13px 0 0 -13px;border-radius:50%;background:var(--flare);box-shadow:0 0 0 8px rgba(255,51,0,.18),0 8px 20px rgba(255,51,0,.5)}

/* lanes */
.lane{position:absolute;left:0;width:620px;height:76px;border:1px solid var(--line);border-radius:18px;background:#fff;overflow:hidden}
.lane .lb{position:absolute;left:18px;top:8px;font-family:var(--mono);font-size:15px;color:#8a847d;letter-spacing:.02em;z-index:2;background:#fff;padding-right:10px}
.lane .env{position:absolute;top:36px;width:22px;height:22px;border-radius:6px;background:#e8e4de}
.lane .otp{position:absolute;top:14px;height:48px;padding:0 18px;border-radius:12px;background:var(--flare);color:#fff;display:flex;align-items:center;gap:10px;font-family:var(--mono);font-size:20px;font-weight:500;white-space:nowrap;box-shadow:0 10px 24px -8px rgba(255,51,0,.6)}

/* pricing */
.slider{position:absolute;left:170px;width:1580px}
.track{position:absolute;left:0;right:0;top:56px;height:8px;border-radius:999px;background:#e9e5df}
.track .fill{position:absolute;left:0;top:0;bottom:0;border-radius:999px;background:var(--flare)}
.thumb{position:absolute;top:60px;width:38px;height:38px;margin:-19px 0 0 -19px;border-radius:50%;background:#fff;border:3px solid var(--flare);box-shadow:0 6px 16px rgba(255,51,0,.35)}
.tick{position:absolute;top:86px;font-family:var(--mono);font-size:17px;color:#8a847d;transform:translateX(-50%)}
.numbox{position:absolute;right:0;top:0;width:260px;height:76px;border:1px solid var(--line);border-radius:6px;background:#fff;text-align:right;padding:0 22px;font-size:44px;line-height:76px;letter-spacing:-.02em}
.pcard{position:absolute;top:0;width:372px;height:462px;border-radius:26px;background:#fff;border:1.5px solid var(--line);padding:30px 30px 0}
.pcard.feat{border:3px solid var(--flare);padding:28px 28px 0}
.pcard .pn{font-size:26px;font-weight:500;display:flex;align-items:center;gap:12px}
.pcard .pn .pill{font-size:15px;padding:6px 14px 6px 12px}
.pcard .pn .pill::before{display:none}
.pcard .pp{margin-top:20px;font-size:76px;letter-spacing:-.045em;font-weight:500;line-height:1}
.pcard .pp small{font-size:24px;letter-spacing:0;color:var(--muted);font-weight:400;margin-left:6px}
.pcard .pt2{margin-top:14px;font-size:20px;color:var(--muted);line-height:1.35;min-height:54px}
.pcard ul{list-style:none;margin-top:22px}
.pcard li{display:flex;gap:12px;font-size:20px;line-height:1.3;margin-bottom:11px;color:#2a2522}
.pcard li svg{width:22px;height:22px;margin-top:2px;color:#6b655f}
.pcard .pb{margin-top:22px;height:56px;border-radius:999px;background:#f2f0ec;border:1px solid var(--line);display:flex;align-items:center;justify-content:center;font-size:22px;font-weight:500}
.pcard.feat .pb{background:var(--flare);color:#fff;border-color:var(--flare)}

/* testimonials */
.tcard{position:absolute;top:0;width:500px;height:520px;border-radius:30px;background:#fff;padding:44px 44px 0;box-shadow:0 1px 2px rgba(26,22,20,.04),0 30px 60px -30px rgba(26,22,20,.2)}
.tcard q{display:block;font-size:33px;line-height:1.3;letter-spacing:-.025em;quotes:"“" "”"}
.tcard .who{position:absolute;left:44px;bottom:44px;display:flex;align-items:center;gap:20px}
.tcard .who img{width:72px;height:72px;border-radius:50%;object-fit:cover}
.tcard .who b{display:block;font-weight:500;font-size:26px}
.tcard .who span{font-size:21px;color:var(--muted)}

/* pain scene (dark) */
.kicker{position:absolute;left:210px;top:150px;font-size:46px;letter-spacing:-.025em;color:var(--muted-d);font-weight:400}
.pw{position:absolute;left:206px;top:250px;font-size:210px;line-height:.94;letter-spacing:-.055em;font-weight:600;color:#f7f8f8}
.pw.md{font-size:150px;top:290px}
.pw.sm{font-size:132px;top:300px;line-height:1}
.pw.fin{font-size:150px;top:0;left:0;width:1920px;height:1080px;display:flex;flex-direction:column;align-items:center;justify-content:center;text-align:center;line-height:1.02}
.pw.fin .fl{color:var(--flare)}
.pw .fl{color:var(--flare)}
.frag{position:absolute;visibility:hidden}
.tpl{position:absolute;width:250px;height:330px;border-radius:20px;background:#121417;border:1px solid rgba(255,255,255,.12);padding:24px}
.tpl i{display:block;height:74px;border-radius:10px;background:#1f2328;margin-bottom:18px}
.tpl b{display:block;height:13px;border-radius:7px;background:#2a2f36;margin-bottom:13px}
.tpl b.s{width:60%}
.tpl .x{position:absolute;right:-16px;top:-16px;width:46px;height:46px;border-radius:50%;background:var(--flare);color:#fff;display:flex;align-items:center;justify-content:center;font-size:26px;font-weight:700}
.setcard{position:absolute;width:560px;padding:26px 30px;border-radius:26px;background:#121417;border:1px solid rgba(255,255,255,.12)}
.setrow{display:flex;align-items:center;justify-content:space-between;height:66px}
.setrow s{display:block;height:15px;border-radius:8px;background:#2a2f36;text-decoration:none}
.tog{position:relative;width:74px;height:40px;border-radius:999px;background:#2a2f36}
.tog::after{content:"";position:absolute;top:5px;left:5px;width:30px;height:30px;border-radius:50%;background:#8a8f98;transform:translateX(var(--k,0px))}
.clockwrap{position:absolute;width:460px;height:460px}
.clockwrap svg{width:460px;height:460px}
.clocklab{position:absolute;left:0;right:0;bottom:-70px;text-align:center;font-family:var(--mono);font-size:38px;color:var(--muted-d);letter-spacing:.02em}
.oldmail{position:absolute;width:520px;background:#e8e5dd;border:3px solid #6f7885;font-family:Arial,Helvetica,sans-serif;color:#333}
.oldmail .oh{background:#3b6ea5;color:#dbe6f3;text-align:center;padding:26px 0;font-size:30px;font-weight:700;letter-spacing:.04em}
.oldmail .ob{padding:26px 28px}
.oldmail .ban{height:150px;background:#c9c6be;border:2px dashed #8b8b8b;display:flex;align-items:center;justify-content:center;font-size:70px;color:#777;margin-bottom:22px}
.oldmail .ln2{height:15px;background:#b9b6ae;margin-bottom:13px}
.oldmail .cta{display:inline-block;margin-top:16px;background:#d9a62a;color:#fff;padding:14px 30px;font-size:24px;font-weight:700;border:2px solid #a07d1c}
.stamp{position:absolute;right:-24px;top:-30px;background:var(--flare);color:#fff;font-family:var(--mono);font-size:30px;font-weight:600;padding:8px 20px;border-radius:8px;transform:rotate(8deg)}

/* nav (hero) */
.nav{position:absolute;left:121px;right:121px;top:0;height:112px;border-bottom:1px solid var(--line);display:flex;align-items:center;padding:0 50px 0 300px;gap:40px;font-size:27px;color:var(--muted)}
.nav .sp{flex:1}
.nav .su{padding:11px 26px;border-radius:999px;background:var(--flare);color:#fff;font-weight:500}
.nav .lg{color:var(--ink)}
.lockup{position:absolute;left:50%;top:50%;display:flex;align-items:center;gap:36px;white-space:nowrap}
.lockup img{width:230px;height:230px;flex:none;filter:drop-shadow(0 24px 30px rgba(255,51,0,.28))}
.lockup span{font-size:190px;font-weight:600;letter-spacing:-.055em;line-height:1}
.hero{position:absolute;left:0;right:0;top:0;bottom:0;display:flex;flex-direction:column;align-items:center;justify-content:center;text-align:center}
.hero h1{font-size:124px;line-height:1.08;letter-spacing:-.05em;font-weight:600;margin-top:34px}
.hero h1 .row{display:block;white-space:nowrap}
.hero h1 .fl{color:var(--flare)}
.hero p{margin-top:38px;font-size:34px;line-height:1.5;color:var(--muted);max-width:900px}
.hero .cta-row{margin-top:40px;display:flex;align-items:center;gap:32px}
.hero .cap{font-size:26px;color:var(--muted);letter-spacing:-.005em}

/* transitions */
.flood{position:absolute;inset:0;z-index:100;clip-path:inset(100% 0 0 0);pointer-events:none}

