@font-face{font-family:"Geist";src:url(fonts/Geist-Variable.woff2) format("woff2");font-weight:100 900;font-display:block}
@font-face{font-family:"Geist Mono";src:url(fonts/GeistMono-Variable.woff2) format("woff2");font-weight:100 900;font-display:block}

:root{
  --void:#08090a; --ink:#1a1614; --paper:#f8f7f4; --flare:#ff3300; --coral:#ff633d;
  --wash:#fbeee7; --peach:#ffe3d9; --line:#e6e1da; --muted:#5f5853; --muted-d:#8a8f98;
  --green:#0a7f64; --band:#f1efeb;
  --mono:"Geist Mono",ui-monospace,monospace;
  --shadow-card:0 1px 2px rgba(26,22,20,.05),0 34px 70px -34px rgba(26,22,20,.28);
}
*{box-sizing:border-box;margin:0;padding:0}
html,body{width:1920px;height:1080px;overflow:hidden;background:#000}
body{font-family:"Geist",Inter,system-ui,sans-serif;color:var(--ink);-webkit-font-smoothing:antialiased;text-rendering:geometricPrecision}
#stage{position:relative;width:1920px;height:1080px;overflow:hidden;background:var(--paper)}
.scene{position:absolute;inset:0;overflow:hidden;background:var(--paper);visibility:hidden}
.scene.dark{background:var(--void);color:#f7f8f8}
.cam{position:absolute;inset:0;transform-origin:50% 50%}
.abs{position:absolute}
svg.ic{width:1em;height:1em;fill:none;stroke:currentColor;stroke-width:2;stroke-linecap:round;stroke-linejoin:round;flex:none}
svg.ic.fill{fill:currentColor;stroke:none}

/* signature hatched rails */
.rails{position:absolute;inset:0;pointer-events:none}
.rails::before,.rails::after{content:"";position:absolute;top:0;bottom:0;width:120px;background:repeating-linear-gradient(135deg,transparent 0 5px,rgba(26,22,20,.085) 5px 6px);background-position:var(--rx,0px) 0}
.rails::before{left:0;border-right:1px solid var(--line)}
.rails::after{right:0;border-left:1px solid var(--line)}
.dark .rails::before,.dark .rails::after{background:repeating-linear-gradient(135deg,transparent 0 5px,rgba(255,255,255,.07) 5px 6px);border-color:rgba(255,255,255,.09)}

/* masks */
.ml{display:inline-block;overflow:hidden;vertical-align:top;padding:.08em .06em .2em;margin:-.08em -.06em -.2em}
.mi{display:inline-block}
.ln{display:block;overflow:hidden;padding:.06em .04em .2em;margin:-.06em -.04em -.2em}
.ln>span{display:block}

/* pill (eyebrow) */
.pill{display:inline-flex;align-items:center;gap:12px;padding:10px 22px 10px 20px;border-radius:999px;background:var(--peach);color:var(--ink);font-size:24px;font-weight:500;letter-spacing:-.01em;white-space:nowrap}
.pill::before{content:"";width:10px;height:10px;border-radius:50%;background:var(--ink)}

/* headline chip */
.chip{display:inline-flex;align-items:center;gap:.18em;padding:0 .22em;margin:0 .06em;border-radius:.26em;background:#fff;border:1px solid var(--line);color:var(--flare);line-height:1.12;white-space:nowrap;vertical-align:baseline;transform:translateY(-.03em);box-shadow:0 1px 2px rgba(26,22,20,.05),0 6px 18px -10px rgba(26,22,20,.2)}
.chip svg{width:.72em;height:.72em;flex:none}

/* buttons */
