const page = await browser.getPage("s55-prof");
await page.setViewportSize({ width: 1920, height: 1080 });
await page.goto("http://127.0.0.1:9271/?v=" + Date.now());
await page.waitForFunction(() => window.__ready === true, null, { timeout: 30000 });
const out = {};
for (const base of [3, 12, 20, 27, 36]) {
  let ts = 0, tp = 0, tj = 0, tsave = 0;
  for (let i = 0; i < 8; i++) {
    const t = base + i / 60;
    let a = Date.now();
    await page.evaluate((tt) => window.__seek(tt), t);
    ts += Date.now() - a;
    a = Date.now();
    const buf = await page.screenshot({ type: "png" });
    tp += Date.now() - a;
    a = Date.now();
    await page.screenshot({ type: "jpeg", quality: 95 });
    tj += Date.now() - a;
    a = Date.now();
    await saveScreenshot(buf, "s55-prof.png");
    tsave += Date.now() - a;
  }
  out[base] = { seek: ts / 8, png: tp / 8, jpg: tj / 8, save: tsave / 8 };
}
console.log(JSON.stringify(out));

