      for (const c of lines) {
        const y = c.buf[c.i];
        c.lp = y * 0.62 + c.lp * 0.38;
        c.buf[c.i] = x + c.lp * 0.86;
        c.i = (c.i + 1) % c.buf.length;
        s += y;
      }
      for (const a of apl) {
        const y = a.buf[a.i];
        const v = s + y * 0.5;
        a.buf[a.i] = v;
        s = y - v * 0.5;
        a.i = (a.i + 1) % a.buf.length;
      }
      out[ch][n] = s;
    }
