  let ph = 0;
  for (let i = 0; i < len; i++) {
    const t = i / SR;
    ph += (TAU * freq) / SR;
    o[i] = (Math.sin(ph) * 0.7 + noise() * 0.35) * env(t, 0.0003, 0.006) * gain;
  }
