  for (let i = 0; i < len; i++) {
    const t = i / SR;
    o[i] = (o[i] + o2[i] * 0.22) * Math.min(1, t / 0.03) * Math.min(1, (dur - t) / 0.06) * gain;
  }
  return o;
}

