  const a = Math.cos(((pan + 1) * Math.PI) / 4);
  const c = Math.sin(((pan + 1) * Math.PI) / 4);
  const L = bus[to + "L"], R = bus[to + "R"];
  for (let i = 0; i < buf.length; i++) {
    const j = start + i;
    if (j < 0) continue;
    if (j >= N) break;
    const v = buf[i] * gain;
    L[j] += v * a;
    R[j] += v * c;
    if (verb) {
      bus.vL[j] += v * a * verb;
      bus.vR[j] += v * c * verb;
    }
  }
