[60, 64, 67, 72].forEach((m, i) => place(pluck(mtof(m), 0.7, 1, 1.4), b(10) + i * 0.012, { gain: 0.3, pan: (i - 1.5) * 0.35, verb: 0.4, to: "m" }));
