/* ---------- reverb (Schroeder, stereo) ---------- */
function reverb(inL, inR) {
  const out = [new Float32Array(N), new Float32Array(N)];
  const combs = [[1557, 1617, 1491, 1422], [1580, 1640, 1514, 1445]];
  const aps = [[225, 556], [241, 579]];
