  const f = svf(raw, (t) => 700 + 5200 * bright * Math.exp(-t * 15), 1.0, "lp");
  for (let i = 0; i < len; i++) {
    const t = i / SR;
    f[i] *= env(t, 0.002, 0.075) * (t > dur - 0.03 ? Math.max(0, (dur - t) / 0.03) : 1) * gain;
