  for (const fr of freqs)
    for (const d of [-9, 0, 9]) {
      const s = saw(fr, len, d);
      for (let i = 0; i < len; i++) raw[i] += s[i] / (freqs.length * 3);
    }
  const f = svf(raw, (t) => 900 + 700 * Math.sin(t * 0.9), 0.8, "lp");
  for (let i = 0; i < len; i++) {
    const t = i / SR;
    f[i] *= Math.min(1, t / 0.4) * Math.min(1, (dur - t) / 0.5) * gain;
  }
