  const len = Math.round(dur * SR);
  const o = new Float32Array(len);
  const parts = [[1, 1, 3.2], [2.756, 0.45, 5], [5.404, 0.22, 8], [0.5, 0.35, 2.4]];
  for (const [m, a, dec] of parts) {
    let ph = 0;
    for (let i = 0; i < len; i++) {
