  for (let i = 0; i < len; i++) raw[i] = noise();
  const f = svf(
    raw,
    (t) => {
      const p = clamp(t / dur);
      const q = up ? p : 1 - p;
      return lo * Math.pow(hi / lo, q * q);
    },
    2.2,
    "bp",
  );
  for (let i = 0; i < len; i++) {
    const p = i / len;
    const e = up ? Math.pow(Math.sin(Math.min(p, 1) * Math.PI * 0.5), 2.2) * (p > 0.92 ? (1 - p) / 0.08 : 1) : Math.pow(Math.cos(p * Math.PI * 0.5), 1.6);
