      const buf = pad(ch.padN.map(mtof), dur, 1);
      const padGain = sec === "G" ? 0.36 : sec === "D" ? 0.3 : sec === "H" ? 0.34 : 0.22;
      for (let i = 0; i < buf.length; i++) buf[i] *= sec === "G" || sec === "H" ? 1 : duck(t + i / SR);
