import { spawn } from "node:child_process";
import { mkdir, readFile, writeFile } from "node:fs/promises";
import { join } from "node:path";
import { fileURLToPath } from "node:url";

const root = join(fileURLToPath(new URL(".", import.meta.url)), "..");
const FPS = Number(process.env.FPS || 60);
const DURATION = 45;
const TOTAL = FPS * DURATION;
const WORKERS = Number(process.env.WORKERS || 9);
const only = process.env.ONLY ? process.env.ONLY.split(",").map(Number) : null;

const template = await readFile(join(root, "tools", "render-chunk.js"), "utf8");
const outDir = join(root, "tools", ".render");
await mkdir(outDir, { recursive: true });

const size = Math.ceil(TOTAL / WORKERS);
const chunks = Array.from({ length: WORKERS }, (_, w) => ({
  w,
  start: w * size,
  end: Math.min(TOTAL, (w + 1) * size),
})).filter((c) => c.start < c.end && (!only || only.includes(c.w)));

async function run(c, attempt) {
  const file = join(outDir, `chunk-${c.w}.js`);
  await writeFile(
    file,
    template
      .replace("__START__", c.start)
      .replace("__END__", c.end)
      .replace("__FPS__", FPS)
      .replace("__PAGE__", `s55-w${c.w}`),
  );
  return new Promise((resolve) => {
    const p = spawn("dev-browser", ["--browser", `s55w${c.w}`, "--headless", "--timeout", "1700", "run", file], {
      stdio: ["ignore", "pipe", "pipe"],
    });
    let out = "";
    p.stdout.on("data", (d) => (out += d));
    p.stderr.on("data", (d) => (out += d));
    p.on("close", (code) => {
      const ok = code === 0 && out.includes('"errs":[]');
      console.log(`chunk ${c.w} [${c.start},${c.end}) attempt ${attempt} ${ok ? "ok" : "FAIL"} ${out.trim().slice(-300)}`);
      resolve(ok);
    });
  });
}

const failed = [];
await Promise.all(
  chunks.map(async (c) => {
    if (!(await run(c, 1)) && !(await run(c, 2))) failed.push(c.w);
  }),
);
if (failed.length) {
  console.error("FAILED chunks:", failed.join(","));
  process.exit(1);
}
console.log(`RENDER_DONE frames=${TOTAL} fps=${FPS}`);

