print("static runs >=30 frames (start s, frames):",runs)
# batch-boundary check: frames whose index % 40 == 0 within pass (approx): compare ydif at boundaries vs neighbours
bad=[]
for i in range(2,len(vals)-2):
    nb=(vals[i-1]+vals[i+1]+vals[i-2]+vals[i+2])/4
